#include <string>
#include <openssl/rc4.h>

std::string computeUValue(std::string const& user_password, QPDF::EncryptionData const& data) {
    // Retrieve encryption key using password and encryption data
    std::string key = data.getKeyFromPassword(user_password);

    // Prepare buffer for U value
    unsigned char u_buffer[data.getUValueLength()];

    // Initialize RC4 with the key and process to generate U value
    RC4_KEY rc4_key;
    RC4_set_key(&rc4_key, key.size(), reinterpret_cast<unsigned char const*>(key.c_str()));
    RC4(&rc4_key, data.getUValueLength(), data.getInitializationVector(), u_buffer);

    return std::string(reinterpret_cast<char*>(u_buffer), data.getUValueLength());
}
